105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
109	        if (normalizedTelephone == null) {
110	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
111	        }
112	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
113	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        LocalDate effectiveDate =
124	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
125	        LocalDate registrationDate = toBusinessDay(effectiveDate);
126	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
127	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        List<Owner> householdMembers =
131	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
132	        if (!sharesHousehold && !householdMembers.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.CONFLICT);
134	        }
135	        HttpHeaders headers = new HttpHeaders();
136	        owner.setTelephone(normalizedTelephone);
137	        owner.setRegistrationDate(registrationDate);
138	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
139	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
140	        if (sharesHousehold && !householdMembers.isEmpty()) {
141	            String householdId = householdId(owner.getLastName(), normalizedAddress);
142	            owner.setHouseholdId(householdId);
143	            for (Owner member : householdMembers) {
144	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
145	                    member.setHouseholdId(householdId);
146	                    this.clinicService.saveOwner(member);
147	                }
148	            }
149	        }
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        headers.setLocation(UriComponentsBuilder.newInstance()
153	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
154	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
155	    }
