242	    /**
243	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
244	     * stripped. When a leading {@code '+'} and country code are present they are kept;
245	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
246	     * is dropped from the national digits. The result must be a {@code '+'} followed
247	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
248	     * is returned to signal a bad request.
249	     */
250	    /**
251	     * Build the customer code for a newly created owner, formatted
252	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
253	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
254	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
255	     * one more than the number of owners already in that city.
256	     */
257	    private String nextCustomerCode(String city, String lastName) {
258	        String cityPrefix = prefixThree(city);
259	        String lastNamePrefix = prefixThree(lastName);
260	        String normalizedCity = normalizeForHousehold(city);
261	        int sequence = (int) this.clinicService.findAllOwners().stream()
262	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
263	            .count() + 1;
264	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
265	    }
266	
267	    /**
268	     * Count the existing owners whose city matches the given one, compared after
269	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
270	     * cap: a city that already holds this many owners is at capacity.
271	     */
272	    private long countOwnersInCity(String city) {
273	        String normalizedCity = normalizeForHousehold(city);
274	        return this.clinicService.findAllOwners().stream()
275	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
276	            .count();
277	    }
278	
279	    /**
280	     * Count the existing owners whose registration date falls on the given day. Used to
281	     * enforce the per-day create limit: once this many owners have been registered today,
282	     * the day is at capacity and further creates are rejected.
283	     */
284	    private long countOwnersRegisteredOn(LocalDate day) {
285	        return this.clinicService.findAllOwners().stream()
286	            .filter(existing -> day.equals(existing.getRegistrationDate()))
287	            .count();
288	    }
289	
290	    /**
291	     * Roll a registration date forward to the next business day: a date falling on a
292	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
293	     * returned unchanged.
294	     */
295	    private LocalDate toBusinessDay(LocalDate date) {
296	        DayOfWeek dayOfWeek = date.getDayOfWeek();
297	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
298	            return date.plusDays(8 - dayOfWeek.getValue());
299	        }
300	        return date;
301	    }
302	
303	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
304	    private String prefixThree(String value) {
305	        String v = value == null ? "" : value;
306	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
307	    }
308	
309	    /**
310	     * Find the existing owners that already belong to the same household as the given
311	     * last name and address, i.e. those sharing both fields. Both are compared
312	     * case-insensitively after collapsing runs of whitespace to a single space and
313	     * trimming the ends.
314	     */
315	    private List<Owner> findHouseholdMembers(String lastName, String address) {
316	        String normalizedLastName = normalizeForHousehold(lastName);
317	        String normalizedAddress = normalizeForHousehold(address);
318	        return this.clinicService.findAllOwners().stream()
319	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
320	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
321	            .toList();
322	    }
323	
324	    /**
325	     * Count the existing owners that already share both the given first and last
326	     * name, compared case-insensitively. Used to populate an owner's namesake count
327	     * at creation time, reflecting how many owners with the same name existed before
328	     * this one was created.
329	     */
330	    private int countNamesakes(String firstName, String lastName) {
331	        String normalizedFirstName = normalizeName(firstName);
332	        String normalizedLastName = normalizeName(lastName);
333	        return (int) this.clinicService.findAllOwners().stream()
334	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
335	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
336	            .count();
337	    }
338	
339	    private String normalizeName(String value) {
340	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
341	    }
342	
343	    /**
344	     * Build a stable identifier shared by all owners of one household. It is derived
345	     * deterministically from the normalized last name and address, so every owner at
346	     * the same household resolves to the same value regardless of creation order.
347	     */
348	    private String householdId(String lastName, String address) {
349	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
350	        try {
351	            byte[] digest = MessageDigest.getInstance("SHA-256")
352	                .digest(key.getBytes(StandardCharsets.UTF_8));
353	            StringBuilder sb = new StringBuilder();
354	            for (int i = 0; i < 6; i++) {
355	                sb.append(String.format("%02X", digest[i]));
356	            }
357	            return "HH-" + sb;
358	        }
359	        catch (NoSuchAlgorithmException e) {
360	            throw new IllegalStateException(e);
361	        }
362	    }
363	
364	    private String normalizeForHousehold(String value) {
365	        if (value == null) {
366	            return "";
367	        }
368	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
369	    }
370	
371	    private String normalizeTelephone(String telephone) {
372	        if (telephone == null) {
373	            return null;
374	        }
375	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
376	        String digits;
377	        if (cleaned.startsWith("+")) {
378	            digits = cleaned.substring(1);
379	        } else {
380	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
381	            digits = "61" + national;
382	        }
383	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
384	    }
385	
386	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
387	    @Override
388	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
389	        Owner owner = this.clinicService.findOwnerById(ownerId);
390	        if (owner != null) {
391	            Pet pet = owner.getPet(petId);
392	            if (pet != null) {
393	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
394	            }
395	        }
396	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
397	    }
398	}
