28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    /** Common street-type abbreviations expanded during address normalization. */
72	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
73	        "ST", "STREET",
74	        "RD", "ROAD",
75	        "AVE", "AVENUE");
76	
77	    /** Fixed city-to-region table used to derive an owner's locality. */
78	    private static final Map<String, String> CITY_REGION = Map.of(
79	        "Sydney", "NSW",
80	        "Melbourne", "VIC",
81	        "Brisbane", "QLD");
82	
83	    public String getAddress() {
84	        return this.address;
85	    }
86	
87	    /**
88	     * Set the owner's address, normalizing it to a canonical form so it is both
89	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
90	     * internal runs of whitespace are collapsed to a single space, the value is
91	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
92	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
93	     * left as-is.
94	     */
95	    public void setAddress(String address) {
96	        this.address = normalizeAddress(address);
97	    }
98	
99	    /**
100	     * Normalize an address string to its canonical form: trimmed, whitespace
101	     * collapsed, upper-cased, with common street-type abbreviations expanded.
102	     * Returns {@code null} for a {@code null} input; a value that is blank once
103	     * trimmed normalizes to the empty string.
104	     */
105	    public static String normalizeAddress(String address) {
106	        if (address == null) {
107	            return null;
108	        }
109	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
110	        if (collapsed.isEmpty()) {
111	            return "";
112	        }
113	        String[] tokens = collapsed.split(" ");
114	        StringBuilder sb = new StringBuilder();
115	        for (int i = 0; i < tokens.length; i++) {
116	            if (i > 0) {
117	                sb.append(' ');
118	            }
119	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
120	        }
121	        return sb.toString();
122	    }
123	
124	    public String getCity() {
125	        return this.city;
126	    }
127	
128	    public void setCity(String city) {
129	        this.city = city;
130	    }
131	
132	    public String getTelephone() {
133	        return this.telephone;
134	    }
135	
136	    public void setTelephone(String telephone) {
137	        this.telephone = telephone;
138	    }
139	
140	    public String getEmail() {
141	        return this.email;
142	    }
143	
144	    /**
145	     * Set the owner's email address, normalizing it to lower case so it is both
146	     * stored and returned in a canonical form. A {@code null} value is left as-is.
147	     */
148	    public void setEmail(String email) {
149	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
150	    }
151	
152	    public LocalDate getRegistrationDate() {
153	        return this.registrationDate;
154	    }
155	
156	    public void setRegistrationDate(LocalDate registrationDate) {
157	        this.registrationDate = registrationDate;
158	    }
159	
160	    public String getCustomerCode() {
161	        return this.customerCode;
162	    }
163	
164	    public void setCustomerCode(String customerCode) {
165	        this.customerCode = customerCode;
166	    }
167	
168	    /**
169	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
170	     * where {@code YY} is the last two digits of the registration date's year (for
171	     * example {@code 'SMI-0007-M26'}). Returns {@code null} when either the customer
172	     * code or the registration date is not set.
173	     */
174	    public String getMembershipNumber() {
175	        if (this.customerCode == null || this.registrationDate == null) {
176	            return null;
177	        }
178	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
179	    }
180	
181	    public String getHouseholdId() {
182	        return this.householdId;
183	    }
184	
185	    public void setHouseholdId(String householdId) {
186	        this.householdId = householdId;
187	    }
188	
189	    public Integer getNamesakeCount() {
190	        return this.namesakeCount;
191	    }
192	
193	    /**
194	     * Return the owner's membership tier: {@code 'SILVER'} when the owner has no
195	     * namesakes (namesake count is {@code 0}) and an email address is present,
196	     * otherwise {@code 'BRONZE'}.
197	     */
198	    public String getMembershipTier() {
199	        boolean hasEmail = this.email != null && !this.email.isBlank();
200	        if (this.namesakeCount != null && this.namesakeCount == 0 && hasEmail) {
201	            return "SILVER";
202	        }
203	        return "BRONZE";
204	    }
205	
206	    public void setNamesakeCount(Integer namesakeCount) {
207	        this.namesakeCount = namesakeCount;
208	    }
209	
210	    /**
211	     * Return the owner's locality, derived from the city using the fixed
212	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
213	     * {@code Brisbane -> QLD}). Returns the canonical region string, or
214	     * {@code 'UNKNOWN'} when the city is not in the table.
215	     */
216	    public String getLocality() {
217	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
218	    }
219	
220	    protected Set<Pet> getPetsInternal() {
221	        if (this.pets == null) {
222	            this.pets = new HashSet<>();
223	        }
224	        return this.pets;
225	    }
226	
227	    protected void setPetsInternal(Set<Pet> pets) {
228	        this.pets = pets;
229	    }
230	
231	    public List<Pet> getPets() {
232	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
233	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
234	        return Collections.unmodifiableList(sortedPets);
235	    }
236	
237	    public void setPets(List<Pet> pets) {
238	        this.pets = new HashSet<>(pets);
239	    }
240	
241	    public void addPet(Pet pet) {
242	        getPetsInternal().add(pet);
243	        pet.setOwner(this);
244	    }
245	
246	    /**
247	     * Return the Pet with the given name, or null if none found for this Owner.
248	     *
249	     * @param name to test
250	     * @return true if pet name is already in use
251	     */
252	    public Pet getPet(String name) {
253	        return getPet(name, false);
254	    }
255	
256	    /**
257	     * Return the Pet with the given name, or null if none found for this Owner.
258	     *
259	     * @param name to test
260	     * @return true if pet name is already in use
261	     */
262	    public Pet getPet(String name, boolean ignoreNew) {
263	        name = name.toLowerCase();
264	        for (Pet pet : getPetsInternal()) {
265	            if (!ignoreNew || !pet.isNew()) {
266	                String compName = pet.getName();
267	                compName = compName.toLowerCase();
268	                if (compName.equals(name)) {
269	                    return pet;
270	                }
271	            }
272	        }
273	        return null;
274	    }
275	
276	    public Pet getPet(Integer petId) {
277	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
278	    }
279	
280	    @Override
281	    public String toString() {
282	        return new ToStringCreator(this)
283	
284	            .append("id", this.getId())
285	            .append("new", this.isNew())
286	            .append("lastName", this.getLastName())
287	            .append("firstName", this.getFirstName())
288	            .append("address", this.address)
289	            .append("city", this.city)
290	            .append("telephone", this.telephone)
291	            .append("email", this.email)
292	            .toString();
293	    }
294	}
